local card={api_version=1,id="EX1_136",name="Redemption",text="<b>Secret:</b> When a friendly minion dies, return it to life with 1 Health.",set="EXPERT1",type="spell",class="paladin",rarity="common",spell_school="holy",cost=1,keywords={"secret"}}
card.triggers={{event="entity_died",timing="after",active_zones={"secret"},condition=function(ctx,self,e)return ctx:get_data(self,"triggered")==0 and e.player==ctx:controller(self)and ctx:entity(e.entity).type=="minion"and #ctx:board(e.player)<7 end,effect=function(ctx,self,e)ctx:continue_with_value("redeem",{entity=e.entity,position=e.position})end}}
function card.redeem(ctx,self,value)if ctx:get_data(self,"triggered")==1 then return end;ctx:set_data(self,"triggered",1);ctx:reveal_secret(self);local d=ctx:card_definition(ctx:entity(value.entity).card_id);ctx:summon_fresh_copy_with_stats(value.entity,value.position,d.attack,1,{})end
return card
